style.css:
@-moz-document domain("codevidhya.com") {
body {
    background-color: #f3e8ff !important; /* pastel lilac */
    font-family: 'Comic Sans MS', cursive, sans-serif !important;
    color: #5a4a6e !important; /* muted purple text */
  }
  /* Hide sidebar or any clutter (adjust selectors as needed) */
  .sidebar, .sidebar-right, .some-sidebar-class {
    display: none !important;
  }
  /* Main content area */
  .main-content, .content-wrapper {
    width: 90% !important;
    background: linear-gradient(135deg, #f9d6e8, #c8e7ff) !important; /* pastel pink to sky blue gradient */
    padding: 20px !important;
    border-radius: 15px !important;
    box-shadow: 0 4px 12px rgba(90, 74, 110, 0.2);
    margin: auto !important;
  }
  /* Links in sky blue */
  a {
    color: #7ec8e3 !important;
  }
  /* Buttons with pastel pink background */
  button, .btn {
    background-color: #f9d6e8 !important; /* pastel pink */
    color: #5a4a6e !important;
    border: none !important;
    border-radius: 10px !important;
    padding: 8px 16px !important;
    font-weight: 600 !important;
    cursor: pointer !important;
    transition: background-color 0.3s ease;
  }
  button:hover, .btn:hover {
    background-color: #d8b0c4 !important; /* slightly deeper lilac pink */
  }
}
